INSERT INTO mcat_question_annotations(question_id,content_version,tagging_version,annotation) VALUES
('cp-partition-oct-q01',1,'1.0.0','{"question_id":"cp-partition-oct-q01","family_id":"cp-partition-oct-q01","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"acid-base.weak-acid-and-weak-base-equilibria","secondary":[],"categories":["5A"],"skill":"S2","secondary_skills":[],"context":["Ionization and membrane partitioning"],"rationale":"For HX ⇌ H+ + X-, pH - pKa = log([X-]/[HX]). A one-unit difference gives [X-]/[HX] = 10. The neutral fraction is therefore 1/(1 + 10), or approximately 9%. The denominator must include both species.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-partition-oct-p01","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-partition-oct-q02',2,'1.0.0','{"question_id":"cp-partition-oct-q02","family_id":"cp-partition-oct-q02","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"membrane-transport.passive-transport","secondary":["acid-base.weak-acid-and-weak-base-equilibria"],"categories":["2A"],"skill":"S2","secondary_skills":[],"context":["Ionization and membrane partitioning"],"rationale":"At pH 5.0, much of the compound is neutral, so the lipid barrier is relatively permissive and delivery through the aqueous layers can become important. Stirring reduces that delivery limitation. At pH 7.0, little neutral compound is available and the membrane-associated limitation dominates, so improving aqueous delivery produces little gain. This explains a change in the relative importance of serial resistances.","uncertainty":"Confirm 2A versus C/P solution-chemistry category for a protein-free barrier.","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"needs-review","passage_id":"cp-partition-oct-p01","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-partition-oct-q03',1,'1.0.0','{"question_id":"cp-partition-oct-q03","family_id":"cp-partition-oct-q03","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"acid-base.weak-acid-and-weak-base-equilibria","secondary":["membrane-transport.passive-transport"],"categories":["5A"],"skill":"S2","secondary_skills":[],"context":["Ionization and membrane partitioning"],"rationale":"Let the common neutral concentration be h. At pH 6.0, [X-] = h and total concentration is 2h. At pH 7.0, [X-] = 10h and total concentration is 11h. The ratio is 11h/(2h) = 11/2. Neutral concentrations equilibrate even though total concentrations differ because ionization occurs within each buffered compartment.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-partition-oct-p01","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-partition-oct-q04',2,'1.0.0','{"question_id":"cp-partition-oct-q04","family_id":"cp-partition-oct-q04","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"experimental-design.controls-and-confounding","secondary":["acid-base.weak-acid-and-weak-base-equilibria"],"categories":["5A"],"skill":"S3","secondary_skills":[],"context":["Ionization and membrane partitioning"],"rationale":"A neutral reference does not undergo the HX-to-X- speciation change. Its weak pH dependence helps distinguish an ionization-related effect on HX from a broad pH effect shared by similarly sized solutes. The reference is supporting evidence; it does not perfectly match every chemical property of HX.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-partition-oct-p01","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-partition-oct-q05',2,'1.0.0','{"question_id":"cp-partition-oct-q05","family_id":"cp-partition-oct-q05","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"spectroscopy.ir-spectroscopy","secondary":["acid-base"],"categories":["4D"],"skill":"S1","secondary_skills":[],"context":["Ionization and membrane partitioning"],"rationale":"Deprotonation removes the carboxylic acid O-H bond, so its broad O-H band decreases or disappears. The carboxylate retains carbon-oxygen bonds; their stretching pattern changes because charge and bonding are delocalized over two oxygens. Other groups elsewhere in HX need not disappear. The question specifically follows the acid group rather than assuming the entire molecule has no other heteroatoms.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-partition-oct-p01","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-ultrasound-oct-q06',1,'1.0.0','{"question_id":"cp-ultrasound-oct-q06","family_id":"cp-ultrasound-oct-q06","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"sound.sound-propagation","secondary":[],"categories":["4D"],"skill":"S2","secondary_skills":[],"context":["Pulse-echo imaging and acoustic interfaces"],"rationale":"The 40-microsecond echo time includes travel to the reflector and back. Depth is ct/2 = (1.50 × 10^3 m/s)(40 × 10^-6 s)/2 = 0.030 m = 3.0 cm. Frequency does not enter this travel-time calculation because sound speed is specified as the same throughout the block.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-ultrasound-oct-p02","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-ultrasound-oct-q07',2,'1.0.0','{"question_id":"cp-ultrasound-oct-q07","family_id":"cp-ultrasound-oct-q07","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"sound.ultrasound-and-attenuation","secondary":[],"categories":["4D"],"skill":"S2","secondary_skills":[],"context":["Pulse-echo imaging and acoustic interfaces"],"rationale":"At 2 MHz, λ = c/f = 0.75 mm; three cycles have a spatial length of 2.25 mm, requiring at least 1.125 mm separation. At 4 MHz, λ = 0.375 mm and the required separation is 0.5625 mm. The actual 0.06 cm equals 0.60 mm, which exceeds H''s threshold but falls below L''s.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-ultrasound-oct-p02","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-ultrasound-oct-q08',1,'1.0.0','{"question_id":"cp-ultrasound-oct-q08","family_id":"cp-ultrasound-oct-q08","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"sound.intensity-and-decibels","secondary":[],"categories":["4D"],"skill":"S2","secondary_skills":[],"context":["Pulse-echo imaging and acoustic interfaces"],"rationale":"The reflected fraction is [(3 - 1)/(3 + 1)]^2 = (2/4)^2 = 0.25. With negligible absorption, reflected plus transmitted intensity fractions sum to one, so transmission is 1 - 0.25 = 0.75, or 75%. The formula concerns intensity, not a pressure-amplitude fraction.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-ultrasound-oct-p02","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-ultrasound-oct-q09',2,'1.0.0','{"question_id":"cp-ultrasound-oct-q09","family_id":"cp-ultrasound-oct-q09","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"data-interpretation.readout-interpretation","secondary":["sound.sound-propagation"],"categories":["4D"],"skill":"S4","secondary_skills":[],"context":["Pulse-echo imaging and acoustic interfaces"],"rationale":"The echo centers occur at the same round-trip time in a material with the same sound speed, so they identify the same depth. H has a smaller received-voltage peak. The higher-frequency attenuation described in the passage is compatible with this reduction, but the graph alone reports voltage rather than an acoustic intensity ratio.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-ultrasound-oct-p02","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-ultrasound-oct-q10',2,'1.0.0','{"question_id":"cp-ultrasound-oct-q10","family_id":"cp-ultrasound-oct-q10","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"sound.ultrasound-and-attenuation","secondary":[],"categories":["4D"],"skill":"S2","secondary_skills":[],"context":["Pulse-echo imaging and acoustic interfaces"],"rationale":"The block attenuates higher frequencies more strongly. A lower frequency can improve the returned signal from depth, but with a fixed cycle count it increases wavelength and spatial pulse length. The same resolution criterion then requires more separation between nearby reflectors. Detection depth and resolving nearby structures are distinct performance goals.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cp-ultrasound-oct-p02","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-renal-oct-q14',1,'1.0.0','{"question_id":"bb-renal-oct-q14","family_id":"bb-renal-oct-q14","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"renal.filtration-reabsorption-secretion","secondary":[],"categories":["3B"],"skill":"S2","secondary_skills":[],"context":["Renal handling and extraction"],"rationale":"Solute I marks filtration because it is freely filtered and is neither secreted nor reabsorbed. After T, excretion is 5.0 mg/mL × 2.0 mL/min = 10 mg/min. Dividing by the arterial concentration of 0.10 mg/mL gives 100 mL/min. The lower urinary concentration is offset by the higher urine flow.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-renal-oct-p03","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-renal-oct-q15',2,'1.0.0','{"question_id":"bb-renal-oct-q15","family_id":"bb-renal-oct-q15","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"renal.filtration-reabsorption-secretion","secondary":[],"categories":["3B"],"skill":"S2","secondary_skills":[],"context":["Renal handling and extraction"],"rationale":"After T, S clearance is (3.0 × 2.0)/0.020 = 300 mL/min, whereas I clearance is 100 mL/min. A freely filtered solute would have clearance equal to GFR if no tubular processing occurred. Because S clearance remains above GFR and S is not generated in the kidney, net tubular secretion adds S to the filtrate.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-renal-oct-p03","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-renal-oct-q16',2,'1.0.0','{"question_id":"bb-renal-oct-q16","family_id":"bb-renal-oct-q16","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"renal.filtration-reabsorption-secretion","secondary":[],"categories":["3B"],"skill":"S4","secondary_skills":[],"context":["Renal handling and extraction"],"rationale":"Before T, S clearance is 500 mL/min and extraction is (0.020 - 0.0020)/0.020 = 0.90. After T, clearance is 300 mL/min and extraction is (0.020 - 0.0092)/0.020 = 0.54. Mass balance gives plasma flow = clearance/extraction: 500/0.90 ≈ 556 and 300/0.54 ≈ 556 mL/min. Reduced clearance reflects reduced extraction rather than reduced delivery in these measurements.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-renal-oct-p03","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-renal-oct-q17',2,'1.0.0','{"question_id":"bb-renal-oct-q17","family_id":"bb-renal-oct-q17","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"membrane-transport.active-transport","secondary":["renal.filtration-reabsorption-secretion"],"categories":["2A"],"skill":"S2","secondary_skills":[],"context":["Renal handling and extraction"],"rationale":"The basolateral Na+/K+ ATPase normally maintains a low intracellular Na+ concentration. The apical symporter uses the resulting inward Na+ gradient to bring Y from filtrate into the cell. Inhibiting the pump weakens that driving force, reducing reabsorption. With filtration held constant, more filtered Y remains available for urinary excretion. The symporter uses secondary active transport rather than directly hydrolyzing ATP.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-renal-oct-p03","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-renal-oct-q18',2,'1.0.0','{"question_id":"bb-renal-oct-q18","family_id":"bb-renal-oct-q18","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"endocrine.hormone-mechanisms","secondary":["renal.urine-concentration"],"categories":["3A"],"skill":"S1","secondary_skills":[],"context":["Renal handling and extraction"],"rationale":"Antidiuretic hormone promotes insertion of water channels, notably aquaporin-2, into the apical membrane of collecting-duct principal cells. Water reabsorption can then increase along the medullary osmotic gradient. At comparable solute excretion, this tends to reduce urine volume and increase urine concentration. The question concerns the hormone''s direct action; the passage does not identify the cause of the original change.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-renal-oct-p03","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-coupling-oct-q19',2,'1.0.0','{"question_id":"bb-coupling-oct-q19","family_id":"bb-coupling-oct-q19","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"oxphos.inhibitors-and-uncoupling","secondary":[],"categories":["1D"],"skill":"S2","secondary_skills":[],"context":["Respiratory coupling and assay interpretation"],"rationale":"Q leaves baseline oxygen consumption at 100 but lowers ATP synthesis from 180 to 90 and reduces the pH difference from 1.0 to 0.5. Additional proton return outside ATP synthase can dissipate part of the gradient without producing ATP, reducing ATP yield per oxygen consumed. Restricting ATP synthase alone would instead tend to increase the gradient and restrain electron transport under these conditions.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-coupling-oct-p04","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-coupling-oct-q20',1,'1.0.0','{"question_id":"bb-coupling-oct-q20","family_id":"bb-coupling-oct-q20","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"data-interpretation.normalization-and-ratios","secondary":[],"categories":["1D"],"skill":"S4","secondary_skills":[],"context":["Respiratory coupling and assay interpretation"],"rationale":"The B-sensitive decrease is 100 - 35 = 65 pmol/min. Background-corrected baseline mitochondrial respiration is 100 - 10 = 90 pmol/min. The requested fraction is 65/90 ≈ 0.72. The numerator is a difference between phases; the denominator excludes the nonmitochondrial or assay background identified after E.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-coupling-oct-p04","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-coupling-oct-q21',2,'1.0.0','{"question_id":"bb-coupling-oct-q21","family_id":"bb-coupling-oct-q21","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"oxphos.electron-transport","secondary":[],"categories":["1D"],"skill":"S1","secondary_skills":[],"context":["Respiratory coupling and assay interpretation"],"rationale":"Oxygen accepts electrons at the end of the mitochondrial respiratory chain. Without it, the chain cannot sustain electron flow and coupled proton pumping. U may provide a proton-return route, but it cannot replace the terminal electron acceptor. ATP synthase can transiently respond to an existing gradient; the primary interruption specified here is electron transfer to oxygen.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-coupling-oct-p04","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-coupling-oct-q22',2,'1.0.0','{"question_id":"bb-coupling-oct-q22","family_id":"bb-coupling-oct-q22","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"experimental-design.controls-and-confounding","secondary":[],"categories":["1D"],"skill":"S3","secondary_skills":[],"context":["Respiratory coupling and assay interpretation"],"rationale":"U-stimulated respiration was measured after B in the main sequence. If B alters substrate handling or another process, the sequence could affect the apparent capacity under U. Obtaining the same rates with U alone checks that particular dependency in these preparations. It does not establish that all assay orders or all compounds are free of effects.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-coupling-oct-p04","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-coupling-oct-q23',2,'1.0.0','{"question_id":"bb-coupling-oct-q23","family_id":"bb-coupling-oct-q23","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"membrane-transport.electrochemical-gradients","secondary":[],"categories":["2A"],"skill":"S1","secondary_skills":[],"context":["Respiratory coupling and assay interpretation"],"rationale":"The driving force for proton movement has chemical and electrical components. The pH difference addresses the chemical component because it reflects the proton concentration ratio. A voltage measurement across the inner membrane is needed to assess the electrical component. A smaller pH difference alone does not quantify the complete proton motive force.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"bb-coupling-oct-p04","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-detection-oct-q27',2,'1.0.0','{"question_id":"ps-detection-oct-q27","family_id":"ps-detection-oct-q27","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"sensation.signal-detection","secondary":[],"categories":["6A"],"skill":"S4","secondary_skills":[],"context":["Detection, response criterion, and divided attention"],"rationale":"The figure gives 276 hits and 64 false alarms in the standard condition. With 400 target-present trials, misses are 400 - 276 = 124. With 400 target-absent trials, correct rejections are 400 - 64 = 336. The smallest category is false alarms, at 64. Response categories use separate denominators for present and absent trials.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-detection-oct-p05","difficulty":"Easy (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-detection-oct-q28',2,'1.0.0','{"question_id":"ps-detection-oct-q28","family_id":"ps-detection-oct-q28","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"sensation.signal-detection","secondary":[],"categories":["6A"],"skill":"S4","secondary_skills":[],"context":["Detection, response criterion, and divided attention"],"rationale":"Standard rates are 276/400 = 0.69 and 64/400 = 0.16, giving d'' = 0.5 - (-1.0) = 1.5. Penalty rates are 0.84 and 0.31, giving 1.0 - (-0.5) = 1.5. Divided-attention rates are 0.62 and 0.31, giving 0.3 - (-0.5) = 0.8. Within the specified approximation, penalty changes reports without increasing the estimated separation of signal and noise.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-detection-oct-p05","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-detection-oct-q29',2,'1.0.0','{"question_id":"ps-detection-oct-q29","family_id":"ps-detection-oct-q29","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"sensation.signal-detection","secondary":[],"categories":["6A"],"skill":"S2","secondary_skills":[],"context":["Detection, response criterion, and divided attention"],"rationale":"The penalty condition increases both hits and false alarms. This is the pattern of a more liberal criterion for reporting target presence: ambiguous evidence is more often classified as a target. Missing a target has become relatively more costly. The approximate sensitivity calculation remains unchanged, which separates the decision-policy interpretation from an improvement in sensory discrimination.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-detection-oct-p05","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-detection-oct-q30',2,'1.0.0','{"question_id":"ps-detection-oct-q30","family_id":"ps-detection-oct-q30","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"experimental-design.controls-and-confounding","secondary":[],"categories":["6A"],"skill":"S3","secondary_skills":[],"context":["Detection, response criterion, and divided attention"],"rationale":"If every participant completed standard trials first and divided-attention trials last, practice, fatigue, or adaptation could be mistaken for condition effects. Counterbalancing distributes positions in the sequence across conditions, reducing that systematic confounding. It does not erase all carryover effects or substitute for controlling the stimulus.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-detection-oct-p05","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-detection-oct-q31',2,'1.0.0','{"question_id":"ps-detection-oct-q31","family_id":"ps-detection-oct-q31","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"conditioning.reinforcement-and-punishment","secondary":[],"categories":["7C"],"skill":"S2","secondary_skills":[],"context":["Detection, response criterion, and divided attention"],"rationale":"The target behavior is correction-key pressing. It terminates an unpleasant tone and becomes more frequent, fitting negative reinforcement. The tone''s introduction after a miss could be considered an aversive consequence of the miss, but that is a different response-consequence relation and does not describe what reinforces the correction-key behavior.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-detection-oct-p05","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-neighborhood-oct-q32',1,'1.0.0','{"question_id":"ps-neighborhood-oct-q32","family_id":"ps-neighborhood-oct-q32","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"data-interpretation.normalization-and-ratios","secondary":[],"categories":["10A"],"skill":"S4","secondary_skills":[],"context":["Built environment, social ties, and causal inference"],"rationale":"Renovation residents increase from 90 to 120, a gain of 30 min/week. Comparison residents increase from 100 to 110, a gain of 10 min/week. Subtracting changes gives 30 - 10 = 20 min/week. This descriptive difference accounts for the measured change in the comparison group; interpreting it as a causal effect requires additional assumptions about comparability and trends.","uncertainty":"Category is contextual: confirm 10A versus 9B; solution only requires comparison of changes.","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"needs-review","passage_id":"ps-neighborhood-oct-p06","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-neighborhood-oct-q33',2,'1.0.0','{"question_id":"ps-neighborhood-oct-q33","family_id":"ps-neighborhood-oct-q33","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"learning-modeling.observational-learning","secondary":[],"categories":["7C"],"skill":"S1","secondary_skills":[],"context":["Built environment, social ties, and causal inference"],"rationale":"Observational learning involves acquiring or modifying behavior by attending to others'' behavior. Watching neighbors demonstrate routines and then trying those routines directly fits modeling. No direct reward to the observer is required by this description. The other findings concern perceived capability, environmental opportunity, and sample selection.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-neighborhood-oct-p06","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-neighborhood-oct-q34',2,'1.0.0','{"question_id":"ps-neighborhood-oct-q34","family_id":"ps-neighborhood-oct-q34","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"identity.self-concept-and-efficacy","secondary":[],"categories":["8A"],"skill":"S1","secondary_skills":[],"context":["Built environment, social ties, and causal inference"],"rationale":"Collective efficacy concerns shared confidence in a group''s capacity for coordinated action, here maintaining a public space. Individual self-efficacy concerns belief in one''s own ability to perform a behavior. Knowledge of an activity and expectations about its outcomes are also distinct from confidence in executing it.","uncertainty":"Confirm collective efficacy placement versus group processes; avoid claiming the individual-only child is sufficient.","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"needs-review","passage_id":"ps-neighborhood-oct-p06","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-neighborhood-oct-q35',2,'1.0.0','{"question_id":"ps-neighborhood-oct-q35","family_id":"ps-neighborhood-oct-q35","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"experimental-design.sampling-and-generalization","secondary":[],"categories":["10A"],"skill":"S3","secondary_skills":[],"context":["Built environment, social ties, and causal inference"],"rationale":"The table describes completers, and residents lost to follow-up had lower baseline activity. Thus the final sample underrepresents that lower-activity portion of the original enrolled population. Equal retained counts do not establish equal selection effects on changes; no follow-up outcomes are supplied for the missing residents. The size and direction of change bias therefore remain unresolved.","uncertainty":"Confirm actual category for a research-methods question; social context alone is not a scored target.","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"needs-review","passage_id":"ps-neighborhood-oct-p06","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-neighborhood-oct-q36',2,'1.0.0','{"question_id":"ps-neighborhood-oct-q36","family_id":"ps-neighborhood-oct-q36","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"inequality.capital-and-social-reproduction","secondary":[],"categories":["10A"],"skill":"S1","secondary_skills":[],"context":["Built environment, social ties, and causal inference"],"rationale":"Bridging social capital concerns connections across otherwise separated social groups. These ties may provide access to information, cooperation, or resources beyond one''s existing circle. Bonding social capital instead emphasizes ties within a relatively close or established group. Neither term by itself guarantees a health benefit.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"ps-neighborhood-oct-p06","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q39',2,'1.0.0','{"question_id":"cars-repair-oct-q39","family_id":"cars-repair-oct-q39","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-main-idea.central-claim","secondary":[],"categories":[],"skill":"CARS-RWT","secondary_skills":[],"context":["Architecture"],"rationale":"The station example denies that one original state automatically dictates the right restoration. The author then evaluates alterations by the evidence they retain or remove and asks institutions to document choices for later scrutiny. The central claim is an accountable process of selection, not a universal priority for surviving use, old materials, or the designer''s plan.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q40',2,'1.0.0','{"question_id":"cars-repair-oct-q40","family_id":"cars-repair-oct-q40","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-context.rhetorical-meaning","secondary":[],"categories":[],"skill":"CARS-FC","secondary_skills":[],"context":["Architecture"],"rationale":"The example concerns a retained street elevation paired with an interior stripped of working traces. A photograph can preserve an attractive or recognizable external appearance while the building loses evidence needed to investigate how it functioned. The distinction concerns what preservation makes available, not a general rejection of visual evidence.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q41',2,'1.0.0','{"question_id":"cars-repair-oct-q41","family_id":"cars-repair-oct-q41","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-main-idea.author-s-position","secondary":[],"categories":[],"skill":"CARS-RWT","secondary_skills":[],"context":["Architecture"],"rationale":"The author separates two questions: whether new housing makes a conversion worthwhile, and what evidence the project preserves. Housing can have a valid claim even when loading doors and circulation routes disappear. Their removal undermines the preservation claim but does not by itself determine the housing benefit.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q42',2,'1.0.0','{"question_id":"cars-repair-oct-q42","family_id":"cars-repair-oct-q42","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-structure.organization-and-relationships","secondary":[],"categories":[],"skill":"CARS-RWT","secondary_skills":[],"context":["Architecture"],"rationale":"The claim challenges an equation of history with untouched material. Maintenance and replacement can be historically meaningful and sustain use. But the following sentences require each alteration to be judged for the intelligibility it sustains or suppresses. Replacing material is not automatically ahistorical, and restored usefulness is not automatically preservation.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q43',2,'1.0.0','{"question_id":"cars-repair-oct-q43","family_id":"cars-repair-oct-q43","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-application.applying-a-principle","secondary":[],"categories":[],"skill":"CARS-RBT","secondary_skills":[],"context":["Architecture"],"rationale":"The warehouse example emphasizes loading doors, circulation routes, and divisions that make working life intelligible. Original machines alone may not explain how a factory operated if their functional relationships can no longer be traced. This case therefore tests the distinction between keeping material and retaining access to evidence of use.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-repair-oct-q44',2,'1.0.0','{"question_id":"cars-repair-oct-q44","family_id":"cars-repair-oct-q44","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-new-information.strengthen-weaken","secondary":[],"categories":[],"skill":"CARS-RBT","secondary_skills":[],"context":["Architecture"],"rationale":"The opening challenges the authority of an unrealized designer''s intention over a building''s actual social life. Period passenger campaigns making the planned roof part of the station''s public identity would give that plan a historical basis beyond the architect''s paperwork. This weakens the example''s contrast between planned form and lived history without making restoration obligatory.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-repair-oct-p07","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q45',2,'1.0.0','{"question_id":"cars-measures-oct-q45","family_id":"cars-measures-oct-q45","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-main-idea.central-claim","secondary":[],"categories":[],"skill":"CARS-RWT","secondary_skills":[],"context":["Political science"],"rationale":"The author accepts counting but shows how categories omit services and rewarded measures change behavior. The remedy is a second view based on actual encounters and institutional purposes, whose errors need not follow the first measure''s incentives. Counts become stronger when corroborated, while divergence warrants investigation rather than an automatic verdict.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q46',2,'1.0.0','{"question_id":"cars-measures-oct-q46","family_id":"cars-measures-oct-q46","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-context.tone-and-attitude","secondary":[],"categories":[],"skill":"CARS-FC","secondary_skills":[],"context":["Political science"],"rationale":"The personification makes an apparently neutral spreadsheet into an advocate. The opening then shows how its categories favor one understanding of achievement without openly naming that position. The tone is ironic: confidence and apparent naturalness conceal choices rather than certify that the ranking represents everyone''s purposes.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q47',2,'1.0.0','{"question_id":"cars-measures-oct-q47","family_id":"cars-measures-oct-q47","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-structure.examples-and-concessions","secondary":[],"categories":[],"skill":"CARS-RWT","secondary_skills":[],"context":["Political science"],"rationale":"The example acknowledges that comparable evidence of use can constrain favoritism based on a branch''s vague reputation or political connections. It gives measurement a genuine democratic benefit, strengthening the later distinction between using metrics and allowing them to define an institution''s whole purpose.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q48',2,'1.0.0','{"question_id":"cars-measures-oct-q48","family_id":"cars-measures-oct-q48","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-context.rhetorical-meaning","secondary":[],"categories":[],"skill":"CARS-FC","secondary_skills":[],"context":["Political science"],"rationale":"An exhibit contributes evidence to an argument; a constitution establishes the governing framework. The preceding sentences concern comparison among purposes and what comparisons omit. The metaphor therefore assigns numbers a role within deliberation while rejecting their authority to set all its ends and rules.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q49',2,'1.0.0','{"question_id":"cars-measures-oct-q49","family_id":"cars-measures-oct-q49","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-application.applying-a-principle","secondary":[],"categories":[],"skill":"CARS-RBT","secondary_skills":[],"context":["Political science"],"rationale":"More students really graduate, just as more books may circulate after libraries respond to loan targets. The concern is that this real improvement can reflect behavior adapted to the reward rather than improvement in the broader purpose, here learning. The finding supports changed interpretation of a measure, not the claim that every favorable number is fabricated.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cars-measures-oct-q50',2,'1.0.0','{"question_id":"cars-measures-oct-q50","family_id":"cars-measures-oct-q50","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"CARS","primary":"cars-application.applying-a-principle","secondary":[],"categories":[],"skill":"CARS-RBT","secondary_skills":[],"context":["Political science"],"rationale":"The second view confirms a consequential activity outside the transaction count. The low loan number can remain accurate while failing to capture that service. The proposed cross-check treats divergence as information about what each measure represents, not proof that a count is false, the institution is wholly efficient, or comparison should cease.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":"cars-measures-oct-p08","difficulty":"Hard (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-discrete-oct-q11',2,'1.0.0','{"question_id":"cp-discrete-oct-q11","family_id":"cp-discrete-oct-q11","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"electrochemistry.cell-potentials","secondary":["thermodynamics","kinetics-chem"],"categories":["4C"],"skill":"S2","secondary_skills":[],"context":["Electrochemistry and thermodynamics"],"rationale":"ΔG° = -nFE°cell, so a positive standard cell potential gives a negative standard Gibbs energy. A catalyst changes the rate of reaching equilibrium by lowering activation barriers; it does not change the free-energy difference between reactants and products, the equilibrium constant, or the standard cell potential.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-discrete-oct-q12',2,'1.0.0','{"question_id":"cp-discrete-oct-q12","family_id":"cp-discrete-oct-q12","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"stereochemistry.enantiomers-and-diastereomers","secondary":["alcohols"],"categories":["5B"],"skill":"S2","secondary_skills":[],"context":["Organic stereochemistry"],"rationale":"SN1 substitution proceeds through a carbocation intermediate with an approximately planar geometry at the reactive carbon. Attack from either face can produce both configurations, reducing enantiomeric excess and therefore optical rotation. Exact racemization need not occur because ion pairing and solvent effects can favor one face.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('cp-discrete-oct-q13',1,'1.0.0','{"question_id":"cp-discrete-oct-q13","family_id":"cp-discrete-oct-q13","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"C/P","primary":"resistors.resistor-networks","secondary":["resistors.electrical-power"],"categories":["4C"],"skill":"S2","secondary_skills":[],"context":["Electric circuits and power"],"rationale":"The parallel equivalent resistance is (1/R + 1/(2R))^-1 = 2R/3. The series equivalent resistance is 3R. At fixed voltage, power is V^2/Req, so Pseries/Pparallel = (2R/3)/(3R) = 2/9. The ideal battery assumption keeps the voltage the same after rewiring.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-discrete-oct-q24',1,'1.0.0','{"question_id":"bb-discrete-oct-q24","family_id":"bb-discrete-oct-q24","content_version":1,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"linkage-meiosis.crossing-over-and-recombination","secondary":[],"categories":["1C"],"skill":"S2","secondary_skills":[],"context":["Meiosis and genetic linkage"],"rationale":"The parental haplotypes are AB and ab. Recombinant gametes are Ab and aB. A recombination frequency of 20% describes their combined frequency, so each reciprocal recombinant type accounts for 10% under the stated assumption. Each parental type then accounts for 40%.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-discrete-oct-q25',2,'1.0.0','{"question_id":"bb-discrete-oct-q25","family_id":"bb-discrete-oct-q25","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"organelles-trafficking.er-golgi-and-protein-trafficking","secondary":[],"categories":["2A"],"skill":"S2","secondary_skills":[],"context":["Protein targeting and secretion"],"rationale":"The ER signal peptide directs a nascent secretory protein toward the ER translocation machinery. Without it or an alternative targeting signal, translation can proceed on cytosolic ribosomes, but the protein is not normally delivered into the ER lumen. It therefore does not proceed through the conventional ER-Golgi secretion route. Actual stability in the cytosol may vary.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('bb-discrete-oct-q26',2,'1.0.0','{"question_id":"bb-discrete-oct-q26","family_id":"bb-discrete-oct-q26","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"B/B","primary":"endocrine.feedback-loops","secondary":[],"categories":["3A"],"skill":"S2","secondary_skills":[],"context":["Endocrine feedback"],"rationale":"Receptor stimulation promotes thyroid hormone production even when pituitary TSH is low. Elevated thyroid hormone feeds back on both the pituitary and hypothalamus, suppressing TSH and TRH, respectively. The antibody bypasses the ordinary need for elevated TSH; it does not remove feedback regulation of upstream hormone release.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-discrete-oct-q37',2,'1.0.0','{"question_id":"ps-discrete-oct-q37","family_id":"ps-discrete-oct-q37","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"attribution.attribution-biases","secondary":[],"categories":["8B"],"skill":"S1","secondary_skills":[],"context":["Attribution and situational constraints"],"rationale":"The observer emphasizes a dispositional trait while overlooking a relevant situational constraint. That is the fundamental attribution error. The description provides the observer''s explanation but no explanation from the actor, so it does not demonstrate the full actor-observer contrast. Identifying the amount of evidence given prevents choosing a related but broader label.","uncertainty":"","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"ai-reviewed","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb),
('ps-discrete-oct-q38',2,'1.0.0','{"question_id":"ps-discrete-oct-q38","family_id":"ps-discrete-oct-q38","content_version":2,"taxonomy_version":"1.0.0","tagging_version":"1.0.0","section":"P/S","primary":"experimental-design.measurement-quality","secondary":[],"categories":["6A"],"skill":"S3","secondary_skills":[],"context":["Reliability and validity"],"rationale":"Stable scores across repeated administrations support test-retest reliability. They do not establish that the instrument measures social isolation. Its stronger relationship with income and weak relationship with an independent social-contact measure raise a construct-validity concern. Social contact is not a perfect definition of isolation, so the evidence raises a concern rather than proving complete invalidity.","uncertainty":"Confirm official category for measurement quality; do not score income or social isolation as prerequisite topics.","reviewer":"Codex solution-based review, 2026-10-10; not independent human validation","review_status":"needs-review","passage_id":null,"difficulty":"Medium (AI-estimated)","difficulty_status":"estimated","published":true}'::jsonb)
